// The user's personal profile, kept as JSON in the Setting table (like the
// assistant and projection settings).
import { prisma } from "@/lib/db";
import { EMPTY_PROFILE, userProfileSchema, type UserProfile, type UserProfileInput } from "@/lib/profileShared";

const KEY = "profile";

/** Stored names are generated by the upload route: avatar-<timestamp>.<ext>. */
export const safePhotoName = (name: unknown) =>
  typeof name === "string" && /^avatar-\d+\.(jpg|png|webp)$/.test(name) ? name : null;

export async function loadProfile(): Promise<UserProfile> {
  const row = await prisma.setting.findUnique({ where: { key: KEY } });
  if (!row) return EMPTY_PROFILE;
  try {
    const raw = JSON.parse(row.value);
    // Field by field: one invalid value (e.g. after a format change) doesn't wipe the rest.
    const profile: Record<string, unknown> = { ...EMPTY_PROFILE };
    for (const [key, schema] of Object.entries(userProfileSchema.shape)) {
      const parsed = schema.safeParse(raw?.[key]);
      if (parsed.success) profile[key] = parsed.data;
    }
    return { ...(profile as unknown as UserProfile), photo: safePhotoName(raw?.photo) };
  } catch {
    return EMPTY_PROFILE;
  }
}

async function write(profile: UserProfile): Promise<void> {
  const value = JSON.stringify(profile);
  await prisma.setting.upsert({ where: { key: KEY }, create: { key: KEY, value }, update: { value } });
}

export async function saveProfile(input: UserProfileInput): Promise<UserProfile> {
  const current = await loadProfile();
  const next = { ...input, photo: current.photo };
  await write(next);
  return next;
}

/** Records the new photo; returns the previous file name so it can be deleted. */
export async function setProfilePhoto(photo: string | null): Promise<string | null> {
  const current = await loadProfile();
  await write({ ...current, photo });
  return current.photo;
}
